From 99e5d36a4c65c7f42c056a8ac46e3aee82228a2f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:20:26 +0100
Subject: [PATCH] foldermodel: keep the arrangement of icons dropped on another
 screen

Icons dragged to another screen were each moved on their own to the
drop point and bumped into each other, ending up in a row. Keep their
offsets from the cursor, scaled to the new grid, and move them at once.

BUG: 481807
---
 .../desktop/plugins/folder/foldermodel.cpp    | 51 ++++++++++++++++---
 .../desktop/plugins/folder/foldermodel.h      |  4 ++
 2 files changed, 49 insertions(+), 6 deletions(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..40222f9d44 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -260,6 +260,7 @@ FolderModel::FolderModel(QObject *parent)
             qCDebug(FOLDER) << "clearing drop target positions after timeout:" << m_dropTargetPositions;
             m_dropTargetPositions.clear();
         }
+        m_dropCursorOffsets.clear();
     });

     m_selectionModel = new QItemSelectionModel(this, this);
@@ -286,12 +287,10 @@ FolderModel::FolderModel(QObject *parent)
                 // Deferred to allow proxies of this to also handle the rowsInserted
                 // we're dealing with URLs here so it's safe to defer here
                 // See BUG:481254
-                QMetaObject::invokeMethod(
-                    this,
-                    [this, pos, url]() {
-                        Q_EMIT move(pos.x(), pos.y(), {url});
-                    },
-                    Qt::QueuedConnection);
+                if (m_pendingDropMoves.isEmpty()) {
+                    QMetaObject::invokeMethod(this, &FolderModel::movePendingDrops, Qt::QueuedConnection);
+                }
+                m_pendingDropMoves[pos].append(url);
             }
         }
     });
@@ -1149,6 +1148,11 @@ void FolderModel::setDragHotSpotScrollOffset(int x, int y)

 QPoint FolderModel::dragCursorOffset(int row)
 {
+    const auto it = m_dropCursorOffsets.constFind(itemForIndex(index(row, 0)).url().fileName());
+    if (it != m_dropCursorOffsets.cend()) {
+        return it.value();
+    }
+
     DragImage *image = m_dragImages.value(row);
     if (!image) {
         return QPoint(0, 0);
@@ -1389,6 +1393,29 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
     if (m_usedByContainment && !m_screenMapper->sharedDesktops()) {
         if (isDropBetweenSharedViews(mimeData->urls(), dropTargetUrl)) {
             setUnsortedModeOnDrop();
+
+            // Keep the arrangement of items dragged from another view, scaled to the cells of this one
+            FolderModel *dragOwner = DragTracker::self()->dragOwner();
+            auto *sourceAdapter = dragOwner ? qobject_cast<ItemViewAdapter *>(dragOwner->m_viewAdapter) : nullptr;
+            auto *targetAdapter = qobject_cast<ItemViewAdapter *>(m_viewAdapter);
+            if (dragOwner != this && sourceAdapter && targetAdapter) {
+                const QObject *sourceView = sourceAdapter->adapterView();
+                const QObject *targetView = targetAdapter->adapterView();
+                const QSizeF sourceCell(sourceView->property("cellWidth").toReal(), sourceView->property("cellHeight").toReal());
+                const QSizeF targetCell(targetView->property("cellWidth").toReal(), targetView->property("cellHeight").toReal());
+                const qreal sourceHitscan = sourceView->property("verticalDropHitscanOffset").toReal();
+                const qreal targetHitscan = targetView->property("verticalDropHitscanOffset").toReal();
+
+                if (!sourceCell.isEmpty() && !targetCell.isEmpty()) {
+                    for (const QModelIndex &index : std::as_const(dragOwner->m_dragIndexes)) {
+                        const QPoint offset = dragOwner->dragCursorOffset(index.row());
+                        const qreal x = (offset.x() + sourceCell.width() / 2) / sourceCell.width() * targetCell.width() - targetCell.width() / 2;
+                        const qreal y = (offset.y() + sourceHitscan) / sourceCell.height() * targetCell.height() - targetHitscan;
+                        m_dropCursorOffsets.insert(dragOwner->itemForIndex(index).url().fileName(), QPointF(x, y).toPoint());
+                    }
+                }
+            }
+
             const QList<QUrl> urls = mimeData->urls();
             for (const auto &url : urls) {
                 m_dropTargetPositions.insert(url.fileName(), dropPos);
@@ -1477,6 +1504,18 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
     });
 }

+void FolderModel::movePendingDrops()
+{
+    // Items dropped together are moved together, so that they don't push each other away
+    const auto pendingDropMoves = std::exchange(m_pendingDropMoves, {});
+    for (auto it = pendingDropMoves.cbegin(); it != pendingDropMoves.cend(); ++it) {
+        Q_EMIT move(it.key().x(), it.key().y(), it.value());
+        for (const QUrl &url : it.value()) {
+            m_dropCursorOffsets.remove(url.fileName());
+        }
+    }
+}
+
 void FolderModel::dropCwd(QObject *dropEvent)
 {
     QMimeData *mimeData = qobject_cast<QMimeData *>(dropEvent->property("mimeData").value<QObject *>());
diff --git a/containments/desktop/plugins/folder/foldermodel.h b/containments/desktop/plugins/folder/foldermodel.h
index c2a2a388f9..c6094a2a8e 100644
--- a/containments/desktop/plugins/folder/foldermodel.h
+++ b/containments/desktop/plugins/folder/foldermodel.h
@@ -363,6 +363,7 @@ private:
     QPoint localMenuPosition() const;
     void createActions();
     void addDragImage(QDrag *drag, int x, int y);
+    void movePendingDrops();
     void setStatus(Status status);
     bool renameTargetStillMatches(const QUrl &oldUrl, const QString &expectedName) const;
     static bool isTrashEmpty();
@@ -383,6 +384,9 @@ private:
     // is not using the URL to easily support desktop:/ URL schemes
     QHash<QString, QPoint> m_dropTargetPositions;
     QTimer *m_dropTargetPositionsCleanup;
+    // target filename to its offset from the cursor in the view the drag came from
+    QHash<QString, QPoint> m_dropCursorOffsets;
+    QHash<QPoint, QList<QUrl>> m_pendingDropMoves;
     QPointer<KFilePreviewGenerator> m_previewGenerator;
     QPointer<KAbstractViewAdapter> m_viewAdapter;
     KActionCollection m_actionCollection;
